body.script:
test(function() {
  assert_background_color('t1', LIME, 'lang=en-GB should be green');
}, 'li:lang(en-GB) matches lang=en-GB');

// Selectors 4 requires malformed element language tags not to match.
// Language-tag and range requirements remain under discussion in
// https://github.com/w3c/csswg-drafts/issues/8720.
test(function() {
  assert_background_color('t2', RED, 'lang=en-GB-wa should be red');
}, 'li:lang(en-GB) does not match malformed lang=en-GB-wa');

test(function() {
  assert_background_color('t5', LIME, 'lang=en-GB-x-wa should be green');
}, 'li:lang(en-GB) matches lang=en-GB-x-wa');

test(function() {
  assert_not_background_color('t3', LIME, 'lang=en-US should not be green');
}, 'li:lang(en-GB) does not match lang=en-US');

test(function() {
  assert_not_background_color('t4', LIME, 'lang=fr should not be green');
}, 'li:lang(en-GB) does not match lang=fr');
